{
  "description": "The creature is shown in right-facing lateral profile against a plain off-white background, standing on four limbs with its body held low to the ground. It has a pale, smooth, rounded head with large dark eyes and a slightly smiling mouth, six feathery reddish-pink external gills projecting from the sides of the neck, a low elongated trunk covered dorsally by large overlapping dark brown scales and ventrally by highly wrinkled pale pink skin with transverse folds, four short thick wrinkled pink legs ending in broad five-toed clawed feet, and a thick tapering tail that extends to the left and is cropped by the edge of the image. The overall appearance combines a soft, naked-skinned ventral body and limbs with a heavily armored scaly back.",
  "parts": [
    {
      "part": "head",
      "looks_like": "pale pink, smooth and slightly glossy, rounded with a blunt snout, small nostril openings at the tip, large round dark eyes with pale bluish-grey irises positioned dorsolaterally, and a faint upturned mouth line; located at the anterior right end of the body"
    ,
      "where": "anterior right end, in front of the gills and scales"
    },
    {
      "part": "eyes",
      "looks_like": "large, round, prominent, dark pupil with a light bluish-grey iris and a small highlight, with slightly wrinkled skin around the orbit",
      "where": "on the sides of the head, one clearly visible in profile on the right side"
    },
    {
      "part": "gills",
      "looks_like": "six external, feathery, branched, reddish-pink filaments with fine lateral fimbriae, fleshy at the base and feathery toward the tips, three on each side of the neck",
      "where": "projecting outward and slightly backward from the posterior sides of the head at the neck junction, just in front of the scaly back"
    },
    {
      "part": "scales",
      "looks_like": "large, overlapping, keratinous, teardrop to rounded plates, dark brown in the center with lighter tan-brown edges and fine radial striations, arranged in diagonal rows",
      "where": "covering the entire dorsal surface from immediately behind the gills over the arched back to the dorsal side of the tail"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, columnar limbs with deeply wrinkled, folded pale pink skin, muscular upper segments and narrower lower segments",
      "where": "two forelimbs under the anterior chest and two hindlimbs under the mid-posterior belly, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad, splayed, five-toed with short pale yellowish claws/nails at the tip of each digit, wrinkled pink skin on the dorsal surface",
      "where": "at the distal ends of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "thick at the base and tapering, scaly dark brown on the dorsal side continuing the back armor and wrinkled pale pink on the ventral side, partially cropped",
      "where": "extending leftward from the posterior body, with only the base and mid-section visible at the left edge of the image"
    },
    {
      "part": "skin / markings",
      "looks_like": "pale pink, highly wrinkled and folded with transverse ridges along the belly and looser folds on the neck and limbs, with faint mottled greyish patches on the top of the head",
      "where": "on the ventral body, neck, sides of the head, and all four limbs, exposed wherever scales are absent"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
